
# =====================================================================
# THE CELLS OF CHAPTER 24 — F9 the divorce (24:1-4), F10 the newlywed, the millstone, the kidnapper and the leprosy (24:5-9), F11 the pledge and the wage (24:10-15), F12 fathers and sons, the stranger and the gleanings (24:16-22)
# =====================================================================
def the_divorce(case, data):
    """F9 — Deut 24:1-4 — ONE LINE divorce_declared writing bill_of_divorce_commanded and divorced_wife_remarriage_permitted (STATUSES), first_husband_retaking_barred and land_caused_to_sin_barred (BLOCKS) — THE NEW FAMILY (no cell of the tape holds the bill; 21:14's release the one earlier mention — refuge_war_family by CALL); the priests' divorcee by CALL (priesthood — Leviticus 21:7); the abomination by CALL (seven_nations); Gittin 9:10, 3:1, 2:4, 8:1, Kiddushin 1:1, Yevamot 10:1 the exam rows"""
    del P_[:]
    ask = case['ask']
    if ask == 'when_a_man_takes_a_wife_and_she_finds_no_favor':
        ink('24:1', "'WHEN A MAN TAKES A WIFE and marries her, and it comes to pass that SHE FINDS NO FAVOR IN HIS EYES because he found in her AN UNSEEMLY THING' — 'an unseemly thing' at %s (23:15's camp the twin); 'when a man takes a wife' 22:13's opening (22:13, 24:1, 24:5 the three takings); the closest kin %s; Onkelos 'a transgression of a word' for the unseemly thing" % (P('ערות', 'דבר', books=T), KINC[(24, 1)][0]))
        move("the Sifrei 268:1-3, 269:1-3 (read whole at the reading — 269 the walk's largest headless piska, fourteen rows); MISHNAH GITTIN 9:10 (the exam row, read whole — CITED IN THE SPINE'S OWN HEBREW at 269:1-3)", "THE GROUNDS: the school of Shammai — a man divorces his wife only if he found in her a matter of unchastity, 'because he found in her an unseemly thing'; the school of Hillel — even if she burned his dish, 'because he found in her an unseemly THING'; R. Akiva — even if he found another fairer than she, 'if she finds no favor in his eyes' (Gittin 9:10 = 269:1-3 — THREE ARMS, each reading its own clause); 'when a man takes' — the marriage before the divorce (268:1); the school of Shammai's 'unchastity' the first arm the spine names")
        dat("THE PARAMETER the_grounds (Gittin 9:10 — Shammai's unchastity, Hillel's burnt dish, R. Akiva's fairer woman: three arms, the ink's 'an unseemly thing' the hole Scripture leaves open); the exam's person who divorces over a burnt dish — Hillel's arm accepted, Shammai's refuses")
        return out("when a man takes a wife and she finds no favor (24:1) — the grounds three arms: Shammai's unchastity, Hillel's burnt dish, R. Akiva's fairer woman, each from its clause; the marriage before the divorce (the Sifrei 268:1-269:3; Mishnah Gittin 9:10 in the spine's own Hebrew): the divorce over a burnt dish Hillel's arm", ['accepted'])
    if ask == 'for_her_name':
        ink('24:1', "'HE SHALL WRITE HER A BILL OF CUTTING-OFF' — 'a bill of cutting-off' at %s alone in the Bible (24:1 and 24:3); 'he shall write HER' — for her name; 24:1 shares %d tokens with 24:3 (%s the shared run — the bill's clause verbatim)" % (P('ספר', 'כריתת', books=None), TWIN['24:1 vs 24:3'], SHARED(DV(24, 1), DV(24, 3))))
        move("the Sifrei 269:4-6 (read whole at the reading); MISHNAH GITTIN 3:1 (the exam row, read whole — CITED IN THE HEBREW at 269:4); MISHNAH GITTIN 2:4 (the exam row, read whole)", "'he shall write HER' — FOR HER NAME: any bill not written for the woman's name is invalid — the scribe's copy for practice, the scribe who wrote for a man who did not come, two wives of one name and he wrote to divorce the elder, 'I will divorce whichever I wish' — all invalid (Gittin 3:1 = 269:4); 'a bill' — a writing: on anything — a leaf, an olive leaf, a cow's horn (giving her the cow), a slave's hand (giving her the slave); R. Yose the Galilean — on nothing living or eaten; not written on what is attached to the ground; R. Judah b. Beteira — not on erased paper or unfinished hide, the sages permit (Gittin 2:4 — the bill's material); 'cutting-off' — a cutting between him and her: a condition that ends is a divorce, one that never ends is not — thirty days (269:6-7 — the reading's find 7)")
        dat("THE PARAMETER the_bills_material (Gittin 2:4 — the leaf, the horn, the slave's hand; the attached to the ground excluded); the_for_her_name a DATA row (Gittin 3:1 — the scribe's copy invalid); the exam's person who divorces with a bill the scribe wrote for practice — the bill invalid, she still his wife")
        return out("for her name (24:1) — the bill written for the woman's name, the scribe's practice copy invalid; a writing on anything not attached to the ground; a cutting that ends (the Sifrei 269:4-7; Mishnah Gittin 3:1 in the spine's own Hebrew, Gittin 2:4): the practice copy divorces no one", ['accepted'])
    if ask == 'the_bill_in_her_hand':
        ink('24:1', "'AND GIVE IT IN HER HAND AND SEND HER FROM HIS HOUSE' — the three acts: he writes, he gives, he sends; 'send her' at 24:1, 24:3, 24:4 (%s the four chapters' sendings); Onkelos 'a bill of release' (get piturin — the answer sheet's own word, the reading's find 4)" % ([(c, v, x) for c, v in SPAN for x in W(c, v) if x.startswith(('שלח', 'לשלח', 'ושלח', 'תשלח'))],))
        move("the Sifrei 269:8-14 (read whole at the reading); MISHNAH GITTIN 8:1 (the exam row, read whole — CITED IN THE HEBREW at 269:14 twice); cold_run_refuge_war_family (CALL) — RW.the_captive(if_you_delight_not_in_her) = %s (21:14's release 'with a divorce document')" % (RW_RELEASE[1],), "'and give it in her hand' — he threw the bill to his wife while she was in her house or in her courtyard — she is divorced; into his house or his courtyard — not divorced, even if she lies with him in the bed (Gittin 8:1 = 269:14: her hand her domain); 'her hand' — her roof, her courtyard, her enclosure (269:13); THE VOID CONDITION — whoever stipulates against what is written in the Torah, his condition is void: R. Tarfon's case (269:8 — the reading's find); 'and send her from his house' — the sending the divorce's act (269:9-12); 21:14's captive released 'with a divorce document' — the one earlier mention of the bill, THIS the bill's own law (refuge_war_family's release by CALL)")
        dat("THE WRITE bill_of_divorce_commanded — a STATUS on israel_people at the chapters' own day (DK2) — THE NEW FAMILY (no cell of the tape held the bill before); THE PARAMETER the_hand_and_the_domain (Gittin 8:1 — her house and her courtyard hers, his not even in the bed); the_void_condition a DATA row (269:8); the exam's person whose bill fell in his wife's courtyard — divorced")
        return out("the bill in her hand (24:1) — her hand her domain: her house or her courtyard divorces, his not even in the bed; the condition against the Torah void; the sending the act; 21:14's release the bill's one earlier mention (the Sifrei 269:8-14; Mishnah Gittin 8:1 in the spine's own Hebrew; refuge_war_family's %s by CALL): THE WRITE bill_of_divorce_commanded, a STATUS on Israel at the chapters' own day — the new family; the bill in her courtyard divorces" % (RW_RELEASE[1][0],), ['bill_of_divorce_commanded'])
    if ask == 'and_she_goes_and_becomes_another_mans':
        ink('24:2-3', "'AND SHE GOES OUT OF HIS HOUSE AND GOES AND BECOMES ANOTHER MAN'S; and the latter man hates her and writes her a bill of cutting-off and gives it in her hand and sends her from his house, or the latter man dies who took her to be his wife' — the closest kin of 24:2 %s (Jeremiah's divorce); the two exits of the second marriage; 24:2 shares %d tokens with Leviticus 21:7 (the priests' divorcee — the restatements that share no words)" % (KINC[(24, 2)][0], TWIN['24:2 vs Lev 21:7'] if '24:2 vs Lev 21:7' in TWIN else 0))
        move("the Sifrei 270:1-8 (read whole at the reading); MISHNAH KIDDUSHIN 1:1 (the exam row, read whole); cold_run_priesthood (CALL) — PR.family(chalutzah) = %s" % (PR_CHAL[0][:2],), "'and becomes another man's' — the divorcee may marry another (270:1); 'the latter man hates her … or the latter man dies' — the two exits of the second marriage, the hate and the death (270:2-4); THE TWO INSTITUTIONS' EXITS ON ONE ROW: a woman is acquired in three ways — money, a document, intercourse — and acquires herself in two — a bill and the husband's death; the levirate widow is acquired by intercourse and acquires herself by the shoe's drawing and the levir's death (Kiddushin 1:1 — the exam row: the school of Shammai a dinar, the school of Hillel a perutah); 270:6 and 270:8 the levirate read before its verse (F14's kin — 270:8's 'chapter 25' the translator's error); the priests' divorcee and the released widow ONE name (Leviticus 21:7 — priesthood's chalutzah by CALL, Makkot 3:1)")
        dat("THE WRITE divorced_wife_remarriage_permitted — a STATUS on israel_people at the chapters' own day (DK2); THE PARAMETER the_acquisitions (Kiddushin 1:1 — three ways in, two out; Shammai's dinar and Hillel's perutah); the_second_marriages_exits a DATA row (the hate and the death — 270:2-4); the exam's person the divorcee who marries a priest — barred by Leviticus 21:7's cell, not by this verse")
        return out("and she goes and becomes another man's (24:2-3) — the divorcee marries another; the second marriage's two exits, the hate and the death; acquired three ways and freed two, the levirate widow's exits on the same row (the Sifrei 270:1-8; Mishnah Kiddushin 1:1; priesthood's %s by CALL): THE WRITE divorced_wife_remarriage_permitted, a STATUS on Israel at the chapters' own day; the divorcee to a priest Leviticus 21:7's bar" % (PR_CHAL[0][0],), ['divorced_wife_remarriage_permitted'])
    if ask == 'her_first_husband_may_not_take_her_back':
        ink('24:4', "'HER FIRST HUSBAND WHO SENT HER AWAY MAY NOT TAKE HER AGAIN to be his wife after she has been defiled, for it is AN ABOMINATION before the LORD; and YOU SHALL NOT CAUSE THE LAND TO SIN which the LORD your God gives you for an inheritance' — the ordinal %s at 24:4 (the first); the abomination noun at %s (24:4's the bare noun among the eleven); 24:4 shares %d tokens with 21:23 (the gift formula's clause — %s)" % (PARSE[(24, 4)][1], U('תועבה', 'תועבת', 'התועבת', 'תועבות', books=('Deut',)), TWIN['24:4 vs 21:23'], SHARED(DV(24, 4), DV(21, 23))))
        move("the Sifrei 270:9-13, 271:1 (read whole at the reading); MISHNAH YEVAMOT 10:1 (the exam row, read whole); cold_run_seven_nations (CALL) — SN.the_images_and_the_devoted(abomination_to_the_lord) = %s" % (SN_ABOM[1],), "'after she has been defiled' — defiled TO HIM: the divorcee who remarried is forbidden to her first husband, not to the priesthood's brother — R. Yose b. Kipper the sotah too (270:10 — the_defilement); 'her first husband … may not take her again' — Jeremiah 3:1 the law as known: 'if a man sends away his wife and she goes from him and becomes another's, shall he return to her again?' (270:11 — the reading's find 10, the Prophets' run citation); the woman whose husband went overseas and they told her he died and she married — and he came: she goes out from this one and from that one, needs a bill from both, no ketubah from both, the child a mamzer from both; R. Yose — her ketubah on her first husband's property; R. Elazar — the first is entitled to her finds and her handiwork; R. Shimon — her intercourse or release with the brother of the first exempts her rival (Yevamot 10:1 — the exam row); 'an abomination' — the formula's seventh seat (seven_nations by CALL); 'you shall not cause the land to sin' — the land's sin a HEAVEN reading, the block on the taker (271:1)")
        dat("THE WRITES first_husband_retaking_barred and land_caused_to_sin_barred — BLOCKS on israel_people at the chapters' own day (DK2); THE PARAMETER the_returned_husband (Yevamot 10:1 — out from both, a bill from both, a mamzer from both; R. Yose's, R. Elazar's, R. Shimon's arms); the_defilement a DATA row (to him, not to the priest — 270:10); the exam's person the first husband who takes back his remarried divorcee — barred, the land caused to sin")
        return out("her first husband may not take her back (24:4) — defiled to him, not to the priest; Jeremiah 3:1 the law as known; the returned husband's wife out from both with a bill from both (the Sifrei 270:9-271:1; Mishnah Yevamot 10:1; seven_nations' %s by CALL): THE WRITES first_husband_retaking_barred and land_caused_to_sin_barred, BLOCKS on Israel at the chapters' own day; the retaking husband barred" % (SN_ABOM[1][0],), ['first_husband_retaking_barred', 'land_caused_to_sin_barred'])
    return 'no verdict in span', [], list(P_)


def the_newlywed_the_millstone_the_kidnapper_and_the_leprosy(case, data):
    """F10 — Deut 24:5-9 — TWO LINES: newlywed_millstone_kidnapper_declared (24:5-7) writing newlywed_year_exemption_commanded and kidnapper_death_commanded (STATUSES) and millstone_pledge_barred (a BLOCK); leprosy_miriam_declared (24:8-9) writing leprosy_priests_teaching_commanded and miriam_remembrance_commanded (STATUSES); 20:7's exemption by CALL (refuge_war_family — Sotah 8:4), the millstone by CALL (ordinances — the Exodus cell's forward reading), the strangled by CALL (sanctions), the purge's ninth seat by CALL (seducers), the tracks by CALL (negaim), Miriam by CALL (beha); Sotah 8:4, Bava Metzia 9:13, Sanhedrin 11:1 the exam rows"""
    del P_[:]
    ask = case['ask']
    if ask == 'a_new_wife_and_one_year':
        ink('24:5', "'When a man takes A NEW WIFE, HE SHALL NOT GO OUT WITH THE ARMY nor shall any matter pass over him; HE SHALL BE FREE FOR HIS HOUSE ONE YEAR and cheer his wife whom he took' — the parser %s at 24:5 (the one year); 24:5 shares %d tokens with 20:7 (the betrothed's exemption); Onkelos 'rejoice with his wife'" % (PARSE[(24, 5)][0], TWIN['24:5 vs 20:7']))
        move("the Sifrei 271:2-7 (read whole at the reading); MISHNAH SOTAH 8:4 (the exam row, read whole); cold_run_refuge_war_family (CALL) — RW.the_priests_speech(the_four_exemptions) = %s" % (RW_FOUR[1],), "'a new wife' — new to him, not the returning divorcee (271:2); 'he shall not go out with the army' — nor supply water and food nor repair the roads: these do not even move from their places — he who built a house and dedicated it, planted a vineyard and used it, married his betrothed, TOOK HIS LEVIRATE WIDOW — 'whom he has taken' (Sotah 8:4 — the exam row; 271:3-5); 20:7's betrothed returns from the ranks, the married of a year does not move (refuge_war_family's exemptions by CALL — Sotah 8:2-3 widened here); 'one year' — the year a CLOCK parameter (271:6 — the reading's find 7); 'and cheer his wife' — Onkelos 'rejoice with his wife' (271:7)")
        dat("THE WRITE newlywed_year_exemption_commanded — a STATUS on israel_people at the chapters' own day (DK2); THE PARAMETERS the_non_movers (Sotah 8:4 — the four who do not move, the levirate widow's taker among them) and the_year (a clock parameter, no timer); the_cheering a DATA row (Onkelos); the exam's person who took his levirate widow this year — does not move from his place")
        return out("a new wife and one year (24:5) — new to him; nor water and food nor the roads — the four who do not move, the levirate widow's taker among them; the year a clock parameter; Onkelos rejoice with his wife (the Sifrei 271:2-7; Mishnah Sotah 8:4; refuge_war_family's %s by CALL): THE WRITE newlywed_year_exemption_commanded, a STATUS on Israel at the chapters' own day; the levirate widow's taker does not move" % (RW_FOUR[1][0],), ['newlywed_year_exemption_commanded'])
    if ask == 'the_millstone_and_the_upper_stone':
        ink('24:6', "'HE SHALL NOT TAKE IN PLEDGE THE MILL OR THE UPPER STONE, for he takes a life in pledge' — no verse of the Bible shares two of its words (KINC %s); 24:6 shares %d tokens with Exodus 22:25 (the pledge)" % (KINC[(24, 6)], TWIN['24:6 vs Exod 22:25']))
        move("the Sifrei 272:1-2 (read whole at the reading); MISHNAH BAVA METZIA 9:13 (the exam row, read whole — the millstone's clause); cold_run_ordinances (CALL) — OR.loan(widow_not_pledged) = %s ('the millstone not taken (Deut 24:6)')" % (OR_WIDOW[0],), "'the mill or the upper stone' — two vessels, two prohibitions: he who takes the mill transgresses one, the mill and the upper stone two (Bava Metzia 9:13's clause — 272:1); 'for he takes a life in pledge' — not these alone but every vessel of food (272:2 — the_food_vessels); THE EXODUS CELL READ THIS VERSE FORWARD — 'the millstone not taken, for he takes a life in pledge (Deut 24:6)' in its own why (ordinances' widow_not_pledged by CALL)")
        dat("THE WRITE millstone_pledge_barred — a BLOCK on israel_people at the chapters' own day (DK2); THE PARAMETER the_food_vessels (every vessel of food — Bava Metzia 9:13 with 272:2); the exam's person the creditor who takes the upper stone alone — one prohibition transgressed")
        return out("the millstone and the upper stone (24:6) — two vessels, two prohibitions; every vessel of food by 'a life'; the Exodus cell read this verse forward (the Sifrei 272:1-2; Mishnah Bava Metzia 9:13; ordinances' %s by CALL): THE WRITE millstone_pledge_barred, a BLOCK on Israel at the chapters' own day; the taker of the upper stone alone transgresses one" % (OR_WIDOW[0],), ['millstone_pledge_barred'])
    if ask == 'the_kidnapper_of_a_soul':
        ink('24:7', "'When a man is found STEALING A SOUL of his brothers, of the sons of Israel, and treats him as a slave and sells him, THAT THIEF SHALL DIE; and you shall purge the evil from your midst' — the purge formula's NINTH AND LAST seat (%s — the formula's seats end at 24:7); 24:7 shares %d tokens with Exodus 21:16 (the kidnapper's Sinai seat — the verse, no cell); Onkelos pali (search out, put away) for the purge" % (P('ובערת', 'הרע', 'מקרבך', books=T), TWIN['24:7 vs Exod 21:16']))
        move("the Sifrei 273:1-9 (read whole at the reading); MISHNAH SANHEDRIN 11:1 (the exam row, read whole); cold_run_sanctions (CALL) — SA.census(strangled) = %s; cold_run_seducers (CALL) — SE.the_readback(the_purge_formulas_nine_seats) = %s; cold_run_mishpatim (CALL) — the Exodus module's F4 read (Exodus 21:16 the kidnapper's verse, no cell)" % (SA_STRANGLED[0], SE_NINE[1]), "'found stealing' — by witnesses (273:1); 'a soul of his brothers' — not a gentile's; 'and treats him as a slave and sells him' — he is not liable until he brings him into his domain and uses him; R. Judah — until he brings him into his domain and uses him; he who steals his own son — R. Ishmael b. R. Yochanan b. Beroka liable, the sages exempt; he who steals one half slave and half free — R. Judah liable, the sages exempt (Sanhedrin 11:1 — the exam row: the kidnapper among the strangled); 'that thief shall die' — strangling, the bare death filled (sanctions' census by CALL); 'and you shall purge the evil' — THE FORMULA'S NINTH AND LAST SEAT: nine seats, all in the book, 13:6 the first (seducers' nine by CALL — the formula CLOSED here); Onkelos 'search out the doer of evil' — the same Aramaic root at 24:20's boughs (the reading's find 12)")
        dat("THE WRITE kidnapper_death_commanded — a STATUS on israel_people at the chapters' own day (DK2); THE PARAMETER the_kidnappers_conditions (Sanhedrin 11:1 — the domain and the use; his own son and the half-slave disputed); the kidnapper's own verdict put_to_death with the evil purged (the body effects reused — the formula's ninth seat); the exam's person who stole a man and sold him before using him — the sages' arm exempt, R. Judah's liable")
        return out("the kidnapper of a soul (24:7) — found by witnesses, brought into his domain and used, then sold: strangled; his own son and the half-slave disputed; the purge formula's ninth and last seat, the formula closed (the Sifrei 273:1-9; Mishnah Sanhedrin 11:1; sanctions' %s and seducers' nine seats by CALL): THE WRITE kidnapper_death_commanded, a STATUS on Israel at the chapters' own day; the seller before the use disputed" % (SA_STRANGLED[0][0],), ['kidnapper_death_commanded', 'put_to_death', 'evil_purged_from_the_midst'])
    if ask == 'take_heed_in_the_plague_of_leprosy':
        ink('24:8', "'TAKE HEED in the plague of leprosy to keep very carefully and to do ACCORDING TO ALL THAT THE LEVITE PRIESTS TEACH YOU; as I commanded them you shall keep to do' — the one imperative of the four chapters (%s — the reading's find 14); the plural 'you' at 24:8 (%s the five verses); 24:8 shares %d tokens with Leviticus 13:2; Onkelos 'take heed in the plague of leprosy' the same noun as 17:8's and 21:5's (%s)" % ([(c, v, x) for c, v in SPAN for x, m in MO[(c, v)] if m and re.search(r'V[a-zA-Z]v', m)], [k for k in SPAN if sum(1 for _, m in MO[k] if m and '2mp' in m)], TWIN['24:8 vs Lev 13:2'], [(17, 8), (21, 5), (24, 8)]))
        move("the Sifrei 274:1-6 (read whole at the reading); cold_run_negaim (CALL) — NG.standing_verdict(skin) = %s, (house) = %s; cold_run_beha (CALL) — BH.miriam(kin_rule) = %s; cold_run_metzora (CALL) — MT.eighth(members) = %s" % (NG_SKIN, NG_HOUSE, BH_KIN[0], MT_MEMBERS[0]), "'take heed' — a prohibition: he who cuts off his mark transgresses (274:1); 'as the priests teach you' — the priest declares: even a learned Israelite examines and instructs him, but the priest says 'unclean' or 'clean' (274:3-4 — the priests' declaration a parameter; beha's 'only a priest declares' by CALL); 'the Levite priests' — even blemished (274:5); 'as I commanded them' — the whole law of the plagues, Leviticus 13-14 the seat: the tracks' standing verdicts and the confinement weeks the Leviticus daemon's timers (negaim's standing_verdict by CALL — RELEASED for the skin, PULL-SCRAPE-PLASTER for the house); the eighth day's right members metzora's (the cell by CALL — F14's right foot)")
        dat("THE WRITE leprosy_priests_teaching_commanded — a STATUS on israel_people at the chapters' own day (DK2); THE PARAMETER the_priests_declaration (the learned Israelite instructs, the priest declares — 274:3-4); the readback row 24:8 a T4 row against the Leviticus cells (no tape line of its own — the daemons' installations); the exam's person who cuts off his mark — barred, the prohibition transgressed")
        return out("take heed in the plague of leprosy (24:8) — a prohibition, the mark not cut off; the learned Israelite instructs, the priest declares; the whole law Leviticus 13-14's — the tracks' standing verdicts (the Sifrei 274:1-6; negaim's %s, beha's declaration and metzora's members by CALL): THE WRITE leprosy_priests_teaching_commanded, a STATUS on Israel at the chapters' own day; the cutter of his mark barred" % (NG_SKIN,), ['leprosy_priests_teaching_commanded'])
    if ask == 'remember_what_the_lord_did_to_miriam':
        ink('24:9', "'REMEMBER WHAT THE LORD YOUR GOD DID TO MIRIAM in the way when you came out of Egypt' — 'remember' the infinitive absolute at 24:9 and 25:17 (%s); 'in the way when you came out of Egypt' the three remembrances' one phrase %s; 24:9 shares %d tokens with 25:17 and %d with Numbers 12:10 (the stroke — no shared word); the closest kin %s" % ([(c, v, x) for c, v in SPAN for x in W(c, v) if x in ('זכור', 'וזכרת', 'זכר')], P('בדרך', 'בצאתכם', 'ממצרים', books=T), TWIN['24:9 vs 25:17'], TWIN['24:9 vs Num 12:10'], KINC[(24, 9)][0]))
        move("the Sifrei 275:1-3 (read whole at the reading); cold_run_beha (CALL) — BH.miriam(remember_miriam) = %s, BH.miriam(who_declared) read" % (BH_REMEMBER[0],), "'remember' — with the mouth (275:1 — the two organs, 296:9's twin); 'what the LORD your God did to Miriam' — the paradigm of evil speech: if Miriam who spoke only against her brother was so struck, how much more he who speaks against his fellow (275:2 — beha's 'the paradigm of evil speech (Deut 24:9)' by CALL: the Numbers cell named THIS verse); the tape's miriam_spoke and miriam_stricken_and_shut_out at Numbers 12:1-15 the readback's REFERENCES — a retelling, never a second act (evil_speech_spoken TWO — aaron, miriam; stricken_with_leprosy ONE — SCANS %s); Micah 6:4 cited (275:3)" % (SCANS['stricken_with_leprosy'],))
        dat("THE WRITE miriam_remembrance_commanded — a STATUS on israel_people at the chapters' own day (DK2); the_remembrance_of_miriam a DATA row (the paradigm — a reference to the tape's own act, no second stroke); the exam's person who reads 24:9 as a second striking of Miriam — the tape's one act at Numbers 12, remembered here")
        return out("remember what the LORD did to Miriam (24:9) — with the mouth; the paradigm of evil speech, the Numbers cell naming this verse; the tape's own act remembered, never a second (the Sifrei 275:1-3; beha's %s by CALL): THE WRITE miriam_remembrance_commanded, a STATUS on Israel at the chapters' own day; no second stroke" % (BH_REMEMBER[1][0],), ['miriam_remembrance_commanded'])
    return 'no verdict in span', [], list(P_)
